-- Guías editoriales de tres escenarios confirmados; no ejecuta operaciones financieras.
INSERT INTO guia_proceso(slug,titulo,categoria,resumen,requisitos,ejemplo,version_contenido,revisada_el,estado) VALUES
('cancelar-pago-pendiente-600',$texto$Cancelar un pago pendiente registrado por error: $600$texto$,'Cobranza',$texto$Corregir un registro de efectivo antes de validarlo: pago cancelado, deuda $600 y caja sin cambios.$texto$,$texto$Alumno e inscripción activos, tutor responsable financiero vigente y caja activa en la moneda de la institución. Administrador persistido autorizado para conceptos, cuotas, adeudos, registrar/cancelar pagos y consultar cuentas. Prueba controlada sin becas, descuentos, recargos ni recepción real de efectivo. No repetir operaciones ya confirmadas al leer la guía.$texto$,$texto$Caso confirmado: cargo $600, abonos $0, saldo $600. Registrar un pago pendiente no modifica la caja; cancelarlo conserva caja B y deuda $600. Si B=$2,000.00, se conserva $2,000.00. Cancelar el pago no cancela el adeudo.$texto$,1,DATE '2026-10-07','CONFIRMADA'),
('cancelar-pago-validado-600',$texto$Cancelar un pago validado registrado por error: $600$texto$,'Cobranza',$texto$Compensar un ingreso registrado por error y retirar sus abonos: caja vuelve a B y deuda vuelve a $600.$texto$,$texto$Cargo de prueba $600 emitido, sin abonos ni ajustes, caja B identificada y usuario administrativo persistido autorizado. Puede ser el adeudo de la guía de pago pendiente después de cancelar ese primer registro. Ninguna devolución ejecutada ni recepción real de efectivo; caja activa con saldo suficiente para compensar. No usar el pago con devolución de otros escenarios.$texto$,$texto$Caso confirmado: pago nuevo $600 validado deja caja B+$600 y deuda $0. Cancelar ese pago deja caja B y deuda $600; conserva pago, ingreso original y compensación históricos. Si B=$2,000.00: $2,600.00 después de validar y $2,000.00 después de cancelar.$texto$,1,DATE '2026-10-07','CONFIRMADA'),
('cancelar-adeudo-sin-abonos-600',$texto$Cancelar un adeudo sin abonos vigentes: $600$texto$,'Cobranza',$texto$Retirar la obligación de cobrar después de cancelar sus pagos: historial $600, saldo exigible cero y caja sin cambios.$texto$,$texto$Adeudo TEST-CANCELACION emitido por $600, sin abonos vigentes (puede conservar pagos históricos cancelados), sin beca/recargo y usuario autorizado para administrar adeudos y consultar cuentas/pagos. Tutor con acceso financiero vigente al alumno para comprobar su portal. Caja B después de la cancelación del pago anterior. No ejecutar sobre obligaciones reales sin motivo autorizado.$texto$,$texto$Caso confirmado: antes de cancelar, original/total $600, Abonos vigentes $0 y Falta por pagar $600. Después, adeudo Cancelado conserva importe histórico $600 y saldo $0; caja B sin variación y cargo ausente en pendientes familiares. Los pagos anteriores siguen Cancelados.$texto$,1,DATE '2026-10-07','CONFIRMADA');
INSERT INTO guia_proceso_permiso(guia_id,permiso_id)
SELECT g.id,p.id FROM guia_proceso g JOIN (VALUES
('cancelar-pago-pendiente-600',ARRAY['CONCEPTO_COBRO_ADMINISTRAR','CUOTA_ALUMNO_ADMINISTRAR','CARGO_ADMINISTRAR','PAGO_LEER','PAGO_REGISTRAR','PAGO_CANCELAR','CUENTA_FINANCIERA_LEER']),
('cancelar-pago-validado-600',ARRAY['CARGO_ADMINISTRAR','PAGO_LEER','PAGO_REGISTRAR','PAGO_VALIDAR','PAGO_CANCELAR','CUENTA_FINANCIERA_LEER']),
('cancelar-adeudo-sin-abonos-600',ARRAY['CARGO_ADMINISTRAR','PAGO_LEER','CUENTA_FINANCIERA_LEER'])
) v(slug,codigos) ON g.slug=v.slug JOIN permiso p ON p.codigo=ANY(v.codigos);
INSERT INTO guia_proceso_paso(guia_id,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta)
SELECT g.id,v.numero,v.titulo,v.perfil,v.modulo,v.instrucciones,v.ejemplo,v.resultado,v.precaucion,v.ruta FROM guia_proceso g JOIN (VALUES
('cancelar-pago-pendiente-600',1,$texto$Preparar el concepto de prueba$texto$,$texto$Administración$texto$,$texto$Conceptos de cobro$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Conceptos de cobro. Busca TEST-CANCELACION y pulsa Aplicar filtros. 2. Si existe, revisa el registro y reutilízalo; no crees otro con el mismo código. Si no existe, pulsa Nuevo registro y selecciona la institución del alumno. 3. Captura Código TEST-CANCELACION, Nombre Prueba de cancelación de pago, Categoría Otro y Activo Sí; deja sin becas, descuentos ni recargos para este caso. 4. Pulsa Crear concepto y comprueba que aparece activo en el listado.$texto$,$texto$Concepto TEST-CANCELACION sin ajustes.$texto$,$texto$Concepto disponible para una cuota individual.$texto$,$texto$No modificar un concepto operativo sólo para reproducir la prueba.$texto$,$texto$/admin/catalogos/conceptos-cobro$texto$),
('cancelar-pago-pendiente-600',2,$texto$Crear una cuota única de $600$texto$,$texto$Administración$texto$,$texto$Cuotas por alumno$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Cuotas por alumno → Nuevo registro. 2. Selecciona institución, plantel, inscripción del alumno y TEST-CANCELACION; enfoca las ayudas para ver opciones o escribe tres caracteres y elige el registro. 3. Configura Una sola vez, Importe 600.00, moneda institucional, Fecha límite de pago vigente dentro de inscripción/ciclo, Estado Activa e Incluir en generación automática de cargos. En Configuración adicional comprueba vigencia e inicio no posterior al corte actual. 4. Pulsa Crear cuota. En Confirmar nueva cuota revisa alumno, concepto, importe, fechas y generación; Cancelar conserva la captura. Para guardar pulsa Confirmar y crear cuota.$texto$,$texto$Cuota única $600.00, sin ajustes ni solapamientos.$texto$,$texto$Cuota guardada; no es un pago ni un cargo todavía.$texto$,$texto$Si ya existe la cuota de esta prueba, consultar su cargo y no duplicarla. No cambiar fechas fuera del rango permitido.$texto$,$texto$/admin/catalogos/cuotas-alumno$texto$),
('cancelar-pago-pendiente-600',3,$texto$Generar sólo el adeudo del ejemplo$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → Generar automáticos. 2. Selecciona institución, plantel y corte actual válido; pulsa Visualizar cuotas por aplicar. 3. Pulsa Desmarcar todos y selecciona únicamente la cuota TEST-CANCELACION del alumno: original $600.00, beca $0.00 y total $600.00. Revisa un registro seleccionado y pulsa Confirmar y generar adeudos seleccionados. 4. Regresa al listado de Adeudos, busca matrícula → Aplicar filtros → Ver del cargo nuevo → Resumen. Anota su número; verifica total $600.00, Abonos vigentes $0.00 y Falta por pagar $600.00.$texto$,$texto$Un adeudo $600.00 para un alumno.$texto$,$texto$Deuda emitida e identificada por número de cargo.$texto$,$texto$No seleccionar otros registros de prueba. Cancelar un cargo no habilita su regeneración automática.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-pago-pendiente-600',4,$texto$Anotar la caja de referencia$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. Busca el código o nombre de la caja de prueba y pulsa Aplicar filtros. 3. Comprueba que es una caja activa compatible con el plantel y moneda del ejemplo. Anota Saldo actual como B. 4. No edites Saldo inicial ni registres entradas manuales: sólo consulta; B sirve para comparar antes y después.$texto$,$texto$Ejemplo B=$2,000.00; usa el saldo real de tu caja.$texto$,$texto$Referencia financiera para demostrar que el pendiente no mueve dinero.$texto$,$texto$Si existen operaciones simultáneas, distinguir sus movimientos; no atribuir cualquier cambio a esta prueba.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('cancelar-pago-pendiente-600',5,$texto$Registrar el pago como pendiente$texto$,$texto$Administración$texto$,$texto$Adeudos → Registrar pago$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del cargo anotado → Resumen → Registrar pago. 2. Conserva tutor/alumno/cargo precargados y verifica Importe $600.00 sin pago parcial. Selecciona Método Efectivo, Cuenta declarada la caja anotada y fecha/hora actual válida. 3. Revisa la distribución de $600.00 al mismo cargo y pulsa Registrar como pendiente. En Confirmar registro del pago verifica tutor, total, caja, método y distribución; Cancelar conserva los datos. Pulsa Confirmar y registrar como pendiente para guardar. 4. Anota el folio automático del nuevo pago y comprueba Pendiente de validación. No pulses Validar y publicar en este caso.$texto$,$texto$Pago pendiente $600.00; adeudo todavía $600.00 y caja B.$texto$,$texto$Registro guardado sin ingreso ni aplicación efectiva.$texto$,$texto$No hubo recepción real de efectivo en este ejemplo controlado. No usar devolución ni validar para cancelar un pendiente.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-pago-pendiente-600',6,$texto$Cancelar el registro pendiente por error$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos. Busca el folio anotado → Aplicar filtros → Ver. 2. Abre Gestión → Cancelar pago registrado por error; captura Motivo Prueba controlada: registro de efectivo capturado por error; no se recibió dinero. 3. Pulsa Cancelar y conservar trazabilidad. En Confirmar cancelación del pago revisa folio, importe $600.00, motivo y Estado actual Pendiente de validación; debe indicar sin cambios en cuenta ni adeudos. 4. Cancelar cierra el modal sin ejecutar; si todo coincide pulsa Confirmar cancelación. Comprueba el aviso y estado Cancelado.$texto$,$texto$Cancelar pago pendiente, no rechazarlo ni cancelar el adeudo.$texto$,$texto$Pago Cancelado con motivo e historial conservados.$texto$,$texto$No confundas Cancelar dentro del modal con Confirmar cancelación. Rechazar sin afectar saldos corresponde a otra decisión.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-pendiente-600',7,$texto$Comprobar que deuda y caja no cambiaron$texto$,$texto$Administración$texto$,$texto$Adeudos, pagos y cuentas$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el folio → Aplicar filtros → Ver y verifica Cancelado con el motivo. 2. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del mismo cargo → Resumen. Debe conservar total $600.00, Abonos vigentes $0.00 y Falta por pagar $600.00, estado Pendiente. 3. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca caja → Aplicar filtros. Saldo actual debe seguir en B. 4. Para probar un pago validado, consulta la guía Cancelar un pago validado registrado por error: $600. Usa un pago nuevo sobre este cargo todavía pendiente; no vuelvas a usar el pago cancelado.$texto$,$texto$Si B=$2,000.00, permanece $2,000.00; la deuda sigue $600.00.$texto$,$texto$Caso pendiente confirmado: cancelar registro sin movimiento de caja ni desaparición de deuda.$texto$,$texto$No canceles el adeudo antes de la siguiente prueba si usarás este mismo cargo.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-validado-600',1,$texto$Identificar el cargo y saldo B$texto$,$texto$Administración$texto$,$texto$Adeudos y cuentas$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del cargo TEST-CANCELACION → Resumen. 2. Comprueba total $600.00, Abonos vigentes $0.00 y Falta por pagar $600.00; anota número de cargo. Si aún no existe, sigue las etapas de preparación de Cancelar un pago pendiente registrado por error: $600. 3. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca la caja → Aplicar filtros y anota Saldo actual como B. 4. No reutilices un cargo ya cancelado ni un pago devuelto: este caso empieza con una deuda todavía exigible y sin abonos.$texto$,$texto$Cargo pendiente $600.00; caja B, por ejemplo $2,000.00.$texto$,$texto$Datos base identificados antes de validar otro pago.$texto$,$texto$La cancelación previa del pendiente no impide registrar un pago nuevo sobre el mismo adeudo.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-pago-validado-600',2,$texto$Registrar un pago nuevo de $600$texto$,$texto$Administración$texto$,$texto$Adeudos → Registrar pago$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del cargo anotado → Resumen → Registrar pago. 2. Verifica tutor y cargo; selecciona Efectivo, caja del ejemplo y fecha/hora actual válida. Comprueba total y distribución $600.00, sin pago parcial. 3. Pulsa Registrar como pendiente; en Confirmar registro del pago revisa importe/caja/cargo y pulsa Confirmar y registrar como pendiente. Cancelar cierra sin guardar si necesitas corregir. 4. Anota el nuevo folio Pendiente de validación. Es otro pago, no el que cancelaste previamente.$texto$,$texto$Segundo registro $600.00 sobre la deuda existente.$texto$,$texto$Nuevo pago pendiente, sin efecto financiero todavía.$texto$,$texto$No crear otra cuota ni otro cargo para pagar la misma deuda.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-pago-validado-600',3,$texto$Validar y comprobar el ingreso antes de cancelar$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca nuevo folio → Aplicar filtros → Ver → Distribución y comprueba $600.00 para el cargo correcto. 2. En Gestión conserva la cuenta destino del ejemplo y pulsa Validar y publicar. En Confirmar validación del pago revisa importe/caja/folio y pulsa Confirmar validación. 3. Comprueba pago Validado; desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos → busca matrícula → Aplicar filtros → Ver → Resumen: abonos $600.00 y falta $0.00. 4. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca caja → Aplicar filtros. Debe ser B más $600.00.$texto$,$texto$B=$2,000.00 → caja=$2,600.00; deuda liquidada temporalmente.$texto$,$texto$Ingreso y abono del pago de prueba confirmados antes de anularlos.$texto$,$texto$En operación real validar sólo dinero efectivamente recibido. Este caso es una prueba controlada de un registro erróneo, no una devolución al tutor.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-validado-600',4,$texto$Cancelar el pago validado con confirmación$texto$,$texto$Administración$texto$,$texto$Pagos recibidos → Gestión$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca el nuevo folio Validado → Aplicar filtros → Ver → Gestión. 2. En Cancelar pago registrado por error captura Motivo Prueba controlada: pago validado por error sin recepción real de efectivo. No uses Rechazar ni Devoluciones. 3. Pulsa Cancelar y conservar trazabilidad. En Confirmar cancelación del pago comprueba estado Validado, folio, monto $600.00, cuenta del ingreso original y egreso compensatorio $600.00. Lee que se liberarán los abonos y recuperará la deuda. 4. Cancelar conserva la captura sin ejecutar. Si todo coincide pulsa Confirmar cancelación y espera estado Cancelado.$texto$,$texto$Compensación $600.00 en la misma cuenta del ingreso original.$texto$,$texto$Pago cancelado; no se borra ni se devuelve dinero por este proceso.$texto$,$texto$No añadir egreso manual ni devolución. Con devoluciones ejecutadas la cancelación está bloqueada; no cambiar de caso para eludirlo.$texto$,$texto$/admin/catalogos/pagos$texto$),
('cancelar-pago-validado-600',5,$texto$Comprobar caja restaurada y deuda recuperada$texto$,$texto$Administración$texto$,$texto$Pagos, cuentas y adeudos$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca nuevo folio → Aplicar filtros → Ver. Comprueba Cancelado y motivo; conserva también el primer pago cancelado del caso pendiente si lo usaste. 2. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca caja → Aplicar filtros. Debe volver a B, sin otras operaciones. 3. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del mismo cargo → Resumen. Debe mostrar total $600.00, Abonos vigentes $0.00, Falta por pagar $600.00 y Pendiente. 4. Deja ese cargo pendiente si continuarás con Cancelar un adeudo sin abonos vigentes: $600. Cancelar el pago no retira la obligación del alumno.$texto$,$texto$Caja $2,600.00 → $2,000.00; deuda $0.00 → $600.00.$texto$,$texto$Caso validado confirmado: caja B restaurada y cargo nuevamente pendiente.$texto$,$texto$No borrar pagos ni registrar otro movimiento compensatorio: el sistema conserva la trazabilidad.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-adeudo-sin-abonos-600',1,$texto$Identificar el adeudo que se retirará$texto$,$texto$Administración$texto$,$texto$Adeudos de alumnos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos. Busca matrícula y pulsa Aplicar filtros. 2. En la fila TEST-CANCELACION del ejemplo pulsa Ver → Resumen. Anota número de cargo y verifica total $600.00, Abonos vigentes $0.00 y Falta por pagar $600.00, estado Pendiente. 3. Si conserva abonos vigentes, detente: el sistema no permite cancelar un cargo pagado. No inventes un descuento para eludir esa regla. Si viene de la guía de pago validado, comprueba que ese pago ya está Cancelado. 4. No crees otro cargo; esta prueba retira la obligación del mismo adeudo después de corregir sus pagos.$texto$,$texto$Adeudo vigente $600.00 sin abonos netos, aunque existan pagos cancelados en el historial.$texto$,$texto$Registro correcto elegido para cancelar.$texto$,$texto$Este caso no certifica cargos con pagos en revisión, convenios o abonos activos.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-adeudo-sin-abonos-600',2,$texto$Anotar que la caja ya volvió a B$texto$,$texto$Administración$texto$,$texto$Cuentas financieras$texto$,$texto$1. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras. 2. Busca caja del ejemplo → Aplicar filtros. 3. Comprueba Saldo actual B, por ejemplo $2,000.00, después de cancelar el pago validado; anótalo para comparar. 4. No modifiques Saldo inicial ni registres movimiento adicional: cancelar un adeudo no entrega ni recibe dinero.$texto$,$texto$Caja B antes de retirar el cobro.$texto$,$texto$Saldo de referencia para confirmar que esta cancelación no afecta fondos.$texto$,$texto$La obligación y el dinero son cosas diferentes: cancelar un adeudo no sustituye una devolución.$texto$,$texto$/admin/catalogos/cuentas-financieras$texto$),
('cancelar-adeudo-sin-abonos-600',3,$texto$Cancelar el adeudo con motivo y modal$texto$,$texto$Administración$texto$,$texto$Adeudos → Ver → Gestión$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula → Aplicar filtros → Ver del cargo anotado → Gestión. 2. En Cancelar adeudo captura Motivo Prueba controlada: se retira el cobro de $600; los pagos registrados por error ya fueron cancelados. No abras Otras gestiones opcionales: Transferencia de cargo vencido y Corregir y reemplazar cargo no son requisitos para cancelar. 3. Pulsa Cancelar cargo al alumno. En Confirmar cancelación del adeudo verifica número, alumno, concepto, total $600.00, abonos $0.00, saldo actual $600.00 y motivo. Lee que deja de ser exigible y no mueve caja/bancos. 4. Cancelar cierra el modal sin ejecutar y conserva motivo. Si todo coincide pulsa Confirmar cancelación del adeudo; comprueba el aviso y estado Cancelado.$texto$,$texto$Retirar deuda $600.00, no devolver ni descontar dinero.$texto$,$texto$Adeudo cancelado con historial y motivo conservados.$texto$,$texto$No usar este botón para corregir una fecha equivocada o devolver un pago real: son procesos diferentes.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-adeudo-sin-abonos-600',4,$texto$Comprobar historial y saldo cero sin otro egreso$texto$,$texto$Administración$texto$,$texto$Adeudos, cuentas y pagos$texto$,$texto$1. Desde el menú lateral entra a Operación escolar → Cobranza escolar → Adeudos de alumnos; busca matrícula, elige Estado Cancelado y pulsa Aplicar filtros. 2. En la fila anotada pulsa Ver → Resumen: conserva original/total histórico $600.00, Abonos vigentes $0.00 y Falta por pagar $0.00. En Gestión consulta Cancelación y su motivo. 3. Desde el menú lateral entra a Administración → Finanzas → Cuentas financieras; busca caja → Aplicar filtros. Saldo actual debe seguir en B; no hay otro egreso por cancelar el adeudo. 4. Desde el menú lateral entra a Administración → Finanzas → Pagos recibidos; busca cada folio anterior → Aplicar filtros → Ver. Deben permanecer Cancelados con sus motivos, no eliminados.$texto$,$texto$Adeudo Cancelado: histórico $600.00, saldo exigible $0.00; caja B.$texto$,$texto$La obligación desaparece del cobro, pero no del historial.$texto$,$texto$Saldo cero por cancelación no significa que se recibieron $600.00. No intentar regenerar una cuota única cancelada.$texto$,$texto$/admin/catalogos/cargos$texto$),
('cancelar-adeudo-sin-abonos-600',5,$texto$Verificar el portal familiar y cerrar el caso$texto$,$texto$Administración y tutor$texto$,$texto$Portal familiar y Guía de procesos$texto$,$texto$1. Abre una ventana privada separada de administración y entra a /familias después de la dirección del sistema con el tutor del alumno. 2. Desde el inicio selecciona al hijo del ejemplo → Tus pagos. En Lo que falta por pagar, el cargo TEST-CANCELACION ya no debe aparecer. 3. En Tus pagos y comprobantes conserva el historial correspondiente; ajusta filtros de mes/año y pulsa Buscar pagos si necesitas localizar los pagos cancelados. No debe ofrecer comprobante oficial de un pago cancelado. 4. En administración entra a Administración → Seguridad y soporte → Guía de procesos y compara las tres guías: pago pendiente sin movimiento, pago validado con compensación y adeudo sin movimiento. No repitas las operaciones por leerlas.$texto$,$texto$Sin $600.00 pendientes familiares; caja B, adeudo/pagos conservados como Cancelados.$texto$,$texto$Las tres cancelaciones del ejemplo fueron confirmadas por el propietario.$texto$,$texto$Cancelar no borra ni reinicia claves automáticas. Para un cobro nuevo legítimo se debe preparar su configuración autorizada; no reactivar esta prueba con cambios improvisados.$texto$,NULL)
) v(slug,numero,titulo,perfil,modulo,instrucciones,ejemplo,resultado,precaucion,ruta) ON g.slug=v.slug;
